//! 🧪️ Original business identity is paid once while every callback and return borrows the actual initiating turn.
use super::*;
fn observe<T>(run:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(run);(value,(heap.requested_bytes,heap.released_bytes))}
fn clock0()->Option<u64>{Some(1000)}fn clock1()->Option<u64>{Some(1001)}fn clock2()->Option<u64>{Some(1002)}
fn grant(row:&serde_json::Value)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:row[0].as_u64().unwrap()as usize,maximum_copy_bytes:row[1].as_u64().unwrap()as usize,maximum_capacity_bytes:row[2].as_u64().unwrap()as usize,maximum_release_bytes:row[3].as_u64().unwrap()as usize,maximum_depth:row[4].as_u64().unwrap()as usize}}
#[derive(semio_framework_value::RetireOwned)]
struct OwnedSemantic{bytes:[u8;7]}
#[test]
fn original_child_source_issues_business_identity_once_and_closes_every_paid_prefix_under_same_parent(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let initial=grant(&law["initialGrant"]);let callback=grant(&law["callbackGrant"]);let close=grant(&law["closeGrant"]);let operation=OperationId(law["parent"]["operation"].as_u64().unwrap());let generation=Generation(law["parent"]["generation"].as_u64().unwrap());let child_operation=OperationId(law["child"]["operation"].as_u64().unwrap());let child_generation=Generation(law["child"]["generation"].as_u64().unwrap());
 for cut in law["cuts"].as_array().unwrap(){let cut=cut.as_u64().unwrap()as usize;let((cancel,birth),heap)=observe(||CancelToken::admit_root(initial).unwrap().unwrap());assert_eq!(heap,(birth.retained_capacity_bytes,0));let mut born=heap.0;let((authority,birth),heap)=observe(||JobPayloadAuthority::admit(operation,generation,initial).unwrap().unwrap());assert_eq!(heap,(birth.retained_capacity_bytes,0));born+=heap.0;let parent_ledger=Arc::as_ptr(authority.original().unwrap());let((mut parent,birth),heap)=observe(||OriginalCallerSourceParent::admit(authority,cancel,initial).ok().unwrap());assert_eq!(heap,(birth.retained_capacity_bytes,0));born+=heap.0;let parent_identity=parent.original.as_ref().unwrap().identity();let mut sequence=0;let mut source=None;let mut released=0;
  if cut>0{let mut posted=Default::default();let mut cx=parent.borrow_context(StepBudget{fuel:4,deadline_us:100000,retained:initial},clock0,&mut sequence,&mut posted).unwrap();let(admitted,heap)=observe(||OriginalCallerChildSource::begin(&parent,&mut cx,child_operation,child_generation).unwrap().unwrap());assert_eq!(heap,(0,0));assert_eq!(cx.retained_progress(),metadata());source=Some(admitted);drop(cx);
   for phase in 1..cut{let mut posted=Default::default();let mut cx=parent.borrow_context(StepBudget{fuel:4,deadline_us:100000,retained:initial},clock0,&mut sequence,&mut posted).unwrap();let(ready,heap)=observe(||source.as_mut().unwrap().admit_step(&parent,&mut cx).unwrap());assert!(!ready);let actual=cx.retained_progress();assert_eq!([actual.copied_items,actual.copied_bytes,actual.retained_capacity_bytes,actual.released_bytes],law["admission"][phase]["spent"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as usize).collect::<Vec<_>>().as_slice());assert_eq!(heap,(actual.retained_capacity_bytes,actual.released_bytes));born+=heap.0;released+=heap.1;}
   if cut==4{let child=source.as_mut().unwrap();let mut posted=Default::default();let mut cx=parent.borrow_context(StepBudget{fuel:4,deadline_us:100000,retained:initial},clock0,&mut sequence,&mut posted).unwrap();assert_eq!(observe(||child.admit_step(&parent,&mut cx).unwrap()),(true,(0,0)));assert_eq!(cx.retained_progress(),Default::default());drop(cx);let child_ledger=Arc::as_ptr(child.parent().unwrap().original.as_ref().unwrap().get().authority.original().unwrap());assert_ne!(child_ledger,parent_ledger);
    for(index,incoming)in law["incoming"].as_array().unwrap().iter().enumerate(){let now:fn()->Option<u64>=match index{0=>clock0,1=>clock1,_=>clock2};let fuel=incoming["fuel"].as_u64().unwrap();let deadline=incoming["deadline"].as_u64().unwrap();let mut posted=Default::default();let mut cx=parent.borrow_context(StepBudget{fuel,deadline_us:deadline,retained:callback},now,&mut sequence,&mut posted).unwrap();let recipient=cx.original_recipient_identity();let(returned,heap)=observe(||child.with_context(&parent,&mut cx,callback,|actual|{assert_eq!(actual.operation(),child_operation);assert_eq!(actual.generation(),child_generation);assert_eq!(actual.deadline_us(),deadline);assert_eq!(actual.fuel_remaining(),fuel);assert_eq!(actual.original_recipient_identity(),recipient);assert_eq!(Arc::as_ptr(&actual.payload_ledger),child_ledger);assert!(actual.original_cancel_token().is_same_node(parent.cancellation().unwrap()));assert_eq!(actual.clock_source()(),incoming["clock"].as_u64());let exact=actual.original_source_parent().unwrap();assert!(std::ptr::eq(exact,child.parent().unwrap()));if fuel==0{assert!(actual.should_yield());return Ok(OwnedSemantic{bytes:[0;7]})}let mut bytes=[0;7];bytes.copy_from_slice(b"source!");actual.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:7,..Default::default()})?;actual.consume_fuel(1);Ok(OwnedSemantic{bytes})}).unwrap());assert_eq!(heap,(0,0));assert!(returned.receipt_refusal().is_none());let raw=returned.raw_progress().unwrap();assert_eq!(raw,cx.retained_progress());let semantic=returned.into_original().ok().unwrap().unwrap();assert_eq!(semantic.bytes,if fuel==0{[0;7]}else{*b"source!"});assert_eq!(cx.fuel_remaining(),fuel.saturating_sub(1));assert_eq!(cx.operation(),operation);assert_eq!(cx.generation(),generation);assert_eq!(parent.original.as_ref().unwrap().identity(),parent_identity);assert_eq!(observe(||drop(semantic)).1,(0,0));}
    let mut posted=Default::default();let mut cx=parent.borrow_context(StepBudget{fuel:4,deadline_us:200000,retained:callback},clock1,&mut sequence,&mut posted).unwrap();let(returned,heap)=observe(||child.with_context(&parent,&mut cx,RetainedCloneGrant{maximum_copy_bytes:6,..callback},|actual|{let mut bytes=[0;7];bytes.copy_from_slice(b"source!");assert!(actual.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:7,..Default::default()}).is_err());Ok(OwnedSemantic{bytes})}).unwrap());assert_eq!(heap,(0,0));assert!(returned.admitted().is_none());assert!(returned.receipt_refusal().is_some());assert_eq!(returned.raw_progress().unwrap(),RetainedCloneProgress{copied_items:1,copied_bytes:7,..Default::default()});let returned=returned.into_original().err().unwrap();assert_eq!(returned.original.as_ref().unwrap().0.as_ref().unwrap().bytes,*b"source!");drop(cx);
    let mut posted=Default::default();let mut cx=parent.borrow_context(StepBudget{fuel:1,deadline_us:200000,retained:callback},clock1,&mut sequence,&mut posted).unwrap();let((mut cursor,birth),heap)=observe(||semio_framework_value::retirement::admit_owned_retirement(returned,cx.retained_grant()).ok().unwrap());cx.consume_retained(birth).unwrap();cx.consume_fuel(1);assert_eq!(heap,(birth.retained_capacity_bytes,0));born+=heap.0;drop(cx);for _ in 0..256{if cursor.terminal_is_empty(){break}let mut posted=Default::default();let mut cx=parent.borrow_context(StepBudget{fuel:1,deadline_us:200000,retained:callback},clock1,&mut sequence,&mut posted).unwrap();let(step,heap)=observe(||cursor.close_step(cx.retained_grant()).unwrap());cx.consume_retained(step.progress()).unwrap();cx.consume_fuel(1);assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.0;released+=heap.1;}assert!(cursor.terminal_is_empty());let frame=birth.retained_capacity_bytes;let mut posted=Default::default();let mut cx=parent.borrow_context(StepBudget{fuel:1,deadline_us:200000,retained:callback},clock1,&mut sequence,&mut posted).unwrap();assert!(RetainedCloneProgress{copied_items:1,released_bytes:frame,..Default::default()}.fits(cx.retained_grant()));let(_,heap)=observe(||drop(cursor));let receipt=RetainedCloneProgress{copied_items:1,released_bytes:heap.1,..Default::default()};cx.consume_retained(receipt).unwrap();cx.consume_fuel(1);assert_eq!(heap,(0,frame));released+=heap.1;
   }
   parent.cancellation().unwrap().cancel_now();for _ in 0..32{if source.as_ref().unwrap().terminal_is_empty(){break}let mut posted=Default::default();let mut cx=parent.borrow_context(StepBudget{fuel:4,deadline_us:250000,retained:close},clock2,&mut sequence,&mut posted).unwrap();let(step,heap)=observe(||source.as_mut().unwrap().close_step(&parent,&mut cx).unwrap());assert_eq!(step.progress(),cx.retained_progress());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(step.progress().fits(close));born+=heap.0;released+=heap.1;}assert!(source.as_ref().unwrap().terminal_is_empty());assert_eq!(observe(||drop(source.take())).1,(0,0));
  }
  for _ in 0..16{if parent.terminal_is_empty(){break}let(step,heap)=observe(||parent.close_step(close).unwrap());assert!(step.progress().fits(close));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.0;released+=heap.1;}assert!(parent.terminal_is_empty());assert_eq!(observe(||drop(parent)).1,(0,0));assert_eq!(born,released);eprintln!("[DEBUG] originalChildSource cut={cut} parent99241/7 child211/19 originalLedgerOnce=true sameCancelNode=true actualSupplier=true receivingOnce=true originalCloseCopy0=true birthRelease={born} terminalDrop0=true");
 }
}
